using System.Reflection;
using System.Runtime.Loader;
using System.Runtime.Serialization;
using System.Text.Json;
using Companion.Bridge;
using HarmonyLib;
var gameRoot=Path.GetFullPath(args[0]);
var output=Environment.GetEnvironmentVariable("STARDEW_COMPANION_DATA")??Path.Combine(Directory.GetCurrentDirectory(),"artifacts","native-bridge-smoke");
Directory.CreateDirectory(output);
AssemblyLoadContext.Default.Resolving+=(context,name)=>{var path=Path.Combine(gameRoot,name.Name+".dll");return File.Exists(path)?context.LoadFromAssemblyPath(path):null;};
var game=AssemblyLoadContext.Default.LoadFromAssemblyPath(Path.Combine(gameRoot,"Stardew Valley.dll"));
if(Environment.GetEnvironmentVariable("DOTNET_STARTUP_HOOKS")==null)Runtime.Attach(game,output);
var update=game.GetType("StardewValley.Game1",true)!.GetMethod("Update",BindingFlags.Instance|BindingFlags.NonPublic)!;
if(!Harmony.GetPatchInfo(update)!.Owners.Contains("com.stardewcompanion.bridge"))throw new Exception("Native update hook was not installed");
var farmerType=game.GetType("StardewValley.Farmer",true)!;
var farmer=FormatterServices.GetUninitializedObject(farmerType);
var field=farmerType.GetField("basicShipped")!;var dictionary=Activator.CreateInstance(field.FieldType)!;
dictionary.GetType().GetMethod("Add",new[]{typeof(string),typeof(int)})!.Invoke(dictionary,new object[]{"390",1});field.SetValue(farmer,dictionary);
if(Runtime.Metric(farmer,new Condition("shipped","390"))!=1)throw new Exception("Native shipped dictionary did not match");
foreach(var (name,source,value)in new[]{("achievements","achievements",(object)0),("mailReceived","mail",(object)"CF_Fair"),("eventsSeen","events",(object)"12345")}){
 var member=farmerType.GetField(name)!;var set=Activator.CreateInstance(member.FieldType)!;set.GetType().GetMethod("Add",new[]{value.GetType()})!.Invoke(set,new[]{value});member.SetValue(farmer,set);
 if(Runtime.Metric(farmer,new Condition(source,value.ToString()!))!=1)throw new Exception("Native set enumeration failed: "+name);
}
var levelField=farmerType.GetField("farmingLevel")!;var level=Activator.CreateInstance(levelField.FieldType)!;level.GetType().GetProperty("Value")!.SetValue(level,10);levelField.SetValue(farmer,level);
if(Runtime.Metric(farmer,new Condition("skill","farming",10))!=10)throw new Exception("Native skill level failed");
var fishField=farmerType.GetField("fishCaught")!;var fish=Activator.CreateInstance(fishField.FieldType)!;fish.GetType().GetMethod("Add",new[]{typeof(string),typeof(int[])})!.Invoke(fish,new object[]{"128",new[]{2,40}});fishField.SetValue(farmer,fish);
if(Runtime.Metric(farmer,new Condition("fish","128"))!=2)throw new Exception("Native fish count failed");
var friendshipField=farmerType.GetField("friendshipData")!;var friendship=Activator.CreateInstance(friendshipField.FieldType)!;
var friend=Activator.CreateInstance(game.GetType("StardewValley.Friendship",true)!,new object[]{750})!;
friendship.GetType().GetMethod("Add",new[]{typeof(string),friend.GetType()})!.Invoke(friendship,new[]{(object)"Abigail",friend});friendshipField.SetValue(farmer,friendship);
if(Runtime.Metric(farmer,new Condition("friendship","Abigail"))!=750)throw new Exception("Native friendship points failed");
if(!game.GetType("StardewValley.ItemRegistry",true)!.GetMethods().Any(m=>m.Name=="GetData"&&m.GetParameters().Length==1))throw new Exception("Native item display lookup signature changed");
var logField=farmerType.GetField("questLog")!;var log=Activator.CreateInstance(logField.FieldType)!;
var quest=Activator.CreateInstance(game.GetType("StardewValley.Quests.Quest",true)!)!;
var setter=typeof(Runtime).GetMethod("Set",BindingFlags.NonPublic|BindingFlags.Static)!;
foreach(var (name,value)in new (string,object)[]{("id","StardewCompanion:test"),("_questTitle","Companion: Ship Stone"),("_questDescription","No reward."),("_currentObjective","Ship Stone"),("accepted",true),("canBeCancelled",true),("showNew",true),("questType",1)})setter.Invoke(null,new[]{quest,name,value});
if((string)Runtime.Read(quest,"_questTitle")! != "Companion: Ship Stone")throw new Exception("Native journal field update failed");
log.GetType().GetMethod("Add")!.Invoke(log,new[]{quest});logField.SetValue(farmer,log);
if(!Runtime.Elements(Runtime.Read(farmer,"questLog")!).Cast<object>().Any(q=>ReferenceEquals(q,quest)))throw new Exception("Native quest list enumeration failed");
var remove=typeof(Runtime).GetMethod("Remove",BindingFlags.NonPublic|BindingFlags.Static)!;remove.Invoke(null,new[]{log,quest});
if(Runtime.Elements(log).Cast<object>().Any())throw new Exception("Native quest list removal failed");
var status=JsonDocument.Parse(File.ReadAllText(Path.Combine(output,"status.json"))).RootElement;
if(status.GetProperty("state").GetString()!="connected")throw new Exception("Connection status missing");
Console.WriteLine("PASS actual vanilla 1.6.15 Game1.Update patched"+(Environment.GetEnvironmentVariable("DOTNET_STARTUP_HOOKS")!=null?" through the .NET startup hook.":" in the isolated compatibility harness."));
Console.WriteLine("PASS actual NetStringDictionary shipping action read from isolated uninitialized Farmer.");
Console.WriteLine("PASS actual NetObjectList quest enumeration and removal preserve the original game types.");
Console.WriteLine("PASS native achievement, mail, event, skill, friendship and fish record adapters.");
Console.WriteLine("PASS actual journal title/objective/flags and item localization signature.");
Console.WriteLine("No game window started, no player save read or written. This does not replace a full gameplay test.");
